class VietnamWardResource extends AdminResource {protected static ?string $model=VietnamWard::class;protected static string $viewPermission='shipping.view';protected static ?string $managePermission='shipping.manage';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedMapPin;protected static ?string $navigationLabel='Gán vùng theo phường';protected static string|\UnitEnum|null $navigationGroup='Bán hàng';protected static ?int $navigationSort=46;public static function form(Schema $s):Schema{return $s->components([Select::make('shipping_zone_id')->relationship('shippingZone','name')->label('Khu vực override')->searchable()->preload()->nullable()]);}public static function table(Table $t):Table{return $t->defaultSort('province_code')->columns([TextColumn::make('code')->label('Mã'),TextColumn::make('full_name')->label('Phường/Xã')->searchable(),TextColumn::make('province_code')->label('Mã tỉnh'),TextColumn::make('shipping_zone_id')->label('ID khu vực')->placeholder('Theo tỉnh')])->recordActions([EditAction::make()->label('Gán khu vực')]);}public static function canCreate():bool{return false;}public static function canDelete(\Illuminate\Database\Eloquent\Model $r):bool{return false;}public static function getPages():array{return ['index'=>ManageVietnamWards::route('/')];}}
